        return (f"finalized {a['latest']['number'] - a['finalized']['number']} block / {a['latest']['ts'] - a['finalized']['ts']} s, safe returned null "
                "(polygon.drpc.org, Geth/v10.0.0/drpc; polygon-bor-rpc.publicnode.com answered a Cloudflare challenge page and polygon-rpc.com HTTP 401)")
